layer.css:
[data-ryt="pitch"] { color: rgb(139, 139, 139); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16.72px; font-weight: 400; font-style: italic; line-height: 1.227; letter-spacing: 1.52px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(139, 139, 139); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: 2.432px; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 1px dashed rgb(192, 192, 192); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 700; font-style: normal; letter-spacing: 1.52px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-border); font-family: var(--ryt-font-heading); font-size: 22.8px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-border); border-radius: 0px; font-family: Georgia, "Times New Roman", Times, serif; font-size: 40px; font-weight: 700; font-style: italic; line-height: 0.482; letter-spacing: 1.52px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-body); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.35; letter-spacing: 1.52px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-text); font-family: Georgia, "Times New Roman", Times, serif; font-size: 10.64px; font-weight: 100; font-style: normal; line-height: 1; letter-spacing: 2.128px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-border); border-bottom: 1px dashed rgb(192, 192, 192); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22.8px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="rec-card"] [data-ryt="title"]::before { content: "# "; display: inline; color: var(--ryt-border); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22.8px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-border) }
[data-ryt="rec-card"] [data-ryt="title"]:hover { border-bottom-width: thin; border-bottom-style: dashed; border-bottom-color: var(--ryt-border) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: inherit; text-decoration-thickness: inherit; text-decoration-style: inherit; text-decoration-color: inherit; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="nav"] a:hover { text-decoration-line: inherit; text-decoration-thickness: inherit; text-decoration-style: inherit; text-decoration-color: inherit; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="brand"]:hover { text-decoration-line: inherit; text-decoration-thickness: inherit; text-decoration-style: inherit; text-decoration-color: inherit; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="hero"] h1::before { content: "# "; display: inline; color: var(--ryt-border); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22.8px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-border) }
[data-ryt="hero"] h1:hover { border-bottom-width: thin; border-bottom-style: dashed; border-bottom-color: var(--ryt-border) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
article[data-ryt="rec-card"]:hover { border-bottom-width: thin; border-bottom-style: dashed; border-bottom-color: var(--ryt-border) }
